import{_ as l,o as t,c as e,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2020-02-24 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2020-02-24 :: Ceph Orchestration Meeting","date":"2020-02-24T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","Distributed Storage","CRUSH Algorithm","High Availability","Scalability","Object Storage","Block Storage","File System Storage","Consistency","Decentralization","Performance","Monitoring","Orchestration","Automation"],"categories":["会议纪要","Ceph 存储","分布式系统","存储架构","存储优化"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-02-24_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2020/2020-02-24_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-02-24_-_-_Ceph_Orchestration_Meeting.md"};function r(n,i,s,h,u,g){return t(),e("div",null,[...i[0]||(i[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期</strong>: 2020-02-24</li><li><strong>参会人员</strong>: [参会人员名单]</li><li><strong>主持人</strong>: [主持人姓名]</li><li><strong>记录人</strong>: [记录人姓名]</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Pull Request讨论</strong></p><ul><li><strong>PR 33442</strong>: 讨论了在生产环境中添加P trace标志的可行性，考虑到安全性和调试需求，决定不无条件添加。</li><li><strong>PR 大Rhenium</strong>: 讨论了将“no”重命名为“host”的请求，认为会增加Ceph的复杂性。</li></ul></li><li><p><strong>测试流程改进</strong></p><ul><li><strong>Brookside测试</strong>: 讨论了如何改进对Orchestrator接口变更的测试，计划使用现有的持续集成系统进行命令行测试。</li><li><strong>Nightly Builds</strong>: 讨论了建立nightly builds的必要性，以检测最新稳定版本的问题。</li></ul></li><li><p><strong>Blinking Lights功能</strong></p><ul><li>讨论了在Python中指定参数和函数结果的改进，以及在实际硬件上测试该功能的必要性。</li></ul></li><li><p><strong>Rook Client迁移</strong></p><ul><li>讨论了将Rook Client从ESF组织迁移到Rook组织的进展，需先解决存储提供者的重构问题。</li></ul></li><li><p><strong>Safe to Fail功能</strong></p><ul><li>讨论了关于Safe to Fail功能的进展，没有新的信息，计划暂时保持现状。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>对于PR 33442，决定不在生产环境中无条件添加P trace标志。</li><li>对于Brookside测试，决定本周内完成初步的命令行测试。</li><li>对于Nightly Builds，决定本周内开始初步的nightly builds测试。</li><li>对于Blinking Lights功能，决定在实际硬件上进行测试。</li><li>对于Rook Client迁移，决定在解决存储提供者重构问题后再进行。</li><li>对于Safe to Fail功能，决定暂时保持现状。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完成PR 33442的安全性评估和决策。</li><li>实施并测试Brookside的命令行测试方案。</li><li>开始并监控nightly builds的实施。</li><li>在实际硬件上测试Blinking Lights功能。</li><li>解决存储提供者重构问题后，迁移Rook Client。</li><li>监控并更新Safe to Fail功能的进展。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议日历条目的问题，决定由相关人员检查并修复。</li></ul><h4 id="下次会议" tabindex="-1">下次会议 <a class="header-anchor" href="#下次会议" aria-label="Permalink to &quot;下次会议&quot;">​</a></h4><ul><li>时间: 下周或明天</li><li>地点: [会议链接或地点]</li></ul><h4 id="备注" tabindex="-1">备注 <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注&quot;">​</a></h4><ul><li>会议中提到的具体PR编号和技术细节需要进一步的技术文档和代码审查。</li></ul>',15)])])}const _=l(o,[["render",r]]);export{c as __pageData,_ as default};
